css:
@keyframes fs-fade-in {
  from {
    opacity: 0;
  }
}

@keyframes fs-fade-out {
  to {
    opacity: 0;
  }
}

@keyframes fs-fade-out-from {
  from {
    opacity: 1;
  }
}

@keyframes fs-pop-in {
  from {
    opacity: 0;
    scale: 0.92;
  }
}

@keyframes fs-swap {
  0% {
    opacity: 0;
    translate: 0 4px;
  }
}

@keyframes fs-card-out {
  from {
    opacity: 1;
    scale: 1;
  }

  to {
    opacity: 0;
    scale: 0.96;
  }
}

@keyframes fs-tether {
  from {
    scale: 0 1;
  }
}

@keyframes fs-halo {
  from {
    box-shadow:
      0 0 0 2px var(--color-bg),
      0 0 0 2px var(--color-accent-soft);
  }
}

@keyframes fs-pointer-down {
  from {
    translate: 0 -166px;
  }
}

@keyframes fs-settle-a {
  from {
    translate: -47.00% 0;
  }
}

@keyframes fs-ring-close {
  from {
    opacity: 0;
    scale: 1.8;
  }
}

@keyframes fs-zoom-open {
  from {
    opacity: 0;
    scale: 0.025 1;
  }
}

@keyframes fs-zoom-close {
  to {
    opacity: 0;
    scale: 0.025 1;
  }
}

@keyframes fs-slide-ruler {
  from {
    translate: 36px 0;
  }
}

@keyframes fs-folio-up {
  from {
    opacity: 0;
    translate: 0 10px;
  }
}

@keyframes fs-step-short {
  from {
    translate: -35.42% 0;
  }
}

4hstVIbr.css:
animation: fs-ring-close 250ms {ease.out} 150ms both;

@media (prefers-reduced-motion: reduce) {
  animation-name: fs-fade-in;
}
transition:
  opacity {transition.duration-pop-exit} {ease.in},
  scale {transition.duration-pop-exit} {ease.in},
  display {transition.duration-pop-exit} allow-discrete;

&[data-state="closed"] {
  display: none;
  opacity: 0;
  scale: 0.96;
}

